mapper.select:
${pagingTop}
SELECT
    ROW_NUMBER() OVER (ORDER BY request_id) AS reverse_rownum, r.lecture_id, r.request_id,
    r.request_name, r.birthday, r.gender, r.phone_number,
    r.email, r.zip_code, r.address1, r.address2, r.request_status, r.request_type,
    r.complete_yn, r.cancel_yn, r.add_date, r.add_ip, r.add_id, r.cancel_date,
    r.cancel_ip, r.cancel_id, i.lecture_title
FROM
    LECTURE_REQUEST as r
INNER JOIN
    LECTURE_INFO as i
ON
    r.lecture_id = i.lecture_id
WHERE
    r.homepage_id = #{homepage_id}

    AND	r.${search_type} LIKE '%'||#{search_text}||'%'



    AND i.course_id = #{search_course_id}


    AND i.lecture_id = #{search_lecture_id}


    AND r.request_type = #{search_request_type}


    AND r.cancel_yn = #{search_cancel_yn}

ORDER BY request_id DESC
${pagingBottom}

SELECT
    COUNT(*)
FROM
    LECTURE_REQUEST as r
INNER JOIN
    LECTURE_INFO as i
ON
    r.lecture_id = i.lecture_id
WHERE
    r.homepage_id = #{homepage_id}

    AND	r.${search_type} LIKE '%'||#{search_text}||'%'



    AND i.course_id = #{search_course_id}


    AND i.lecture_id = #{search_lecture_id}


    AND r.request_type = #{search_request_type}


    AND r.cancel_yn = #{search_cancel_yn}
